const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const northEthiopia = ee.Geometry.Polygon([[
    [36.4, 14.8], [42.0, 14.8], [42.0, 9.0], [36.4, 9.0], [36.4, 14.8]
  ]]);
  const southEthiopia = ee.Geometry.Polygon([[
    [34.5, 9.0], [42.0, 9.0], [42.0, 3.5], [34.5, 3.5], [34.5, 9.0]
  ]]);

  const recentStartDate = '2021-10-01';
  const recentEndDate = '2021-12-01'; // Exclusive end date

  const baselineStartYear = 2000;
  const baselineEndYear = 2013;
  const baselineMonthStart = 10;
  const baselineMonthEnd = 11;

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Recent period data
  const recentCollection = chirps.filterDate(recentStartDate, recentEndDate);

  // Baseline period data
  const baselineCollection = chirps
    .filter(ee.Filter.calendarRange(baselineStartYear, baselineEndYear, 'year'))
    .filter(ee.Filter.calendarRange(baselineMonthStart, baselineMonthEnd, 'month'));

  // 3. Data Availability Check
  const recentSize = recentCollection.size().getInfo();
  const baselineSize = baselineCollection.size().getInfo();

  if (recentSize === 0 || baselineSize === 0) {
    console.log(`Recent image count: ${recentSize}`);
    console.log(`Baseline image count: ${baselineSize}`);
    console.log('C1: Empty Collection. No images found for one or both periods.');
    console.log('A'); // This line will be ignored by the platform but is a placeholder
    return;
  }
  console.log(`Recent image count (Oct-Nov 2021): ${recentSize}`);
  console.log(`Baseline image count (Oct-Nov 2000-2013): ${baselineSize}`);

  // 4. Processing & Calculation
  // Calculate total rainfall for the recent period
  const totalRecent = recentCollection.sum();

  // Calculate total rainfall for each year in the baseline period
  const years = ee.List.sequence(baselineStartYear, baselineEndYear);
  const annualTotals = ee.ImageCollection.fromImages(
    years.map(function(y) {
      const yearStart = ee.Date.fromYMD(y, baselineMonthStart, 1);
      const yearEnd = yearStart.advance(2, 'month'); // Covers Oct and Nov
      const total = baselineCollection.filterDate(yearStart, yearEnd).sum();
      return total.set('year', y);
    })
  );

  // Calculate long-term average (mean of annual totals)
  const baselineMean = annualTotals.mean();

  const scale = 5000; // Use a coarse scale to avoid timeouts

  // Function to calculate mean rainfall in a region
  const getMean = (image, region) => image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation');

  // Get all values
  const recentNorthVal = getMean(totalRecent, northEthiopia);
  const recentSouthVal = getMean(totalRecent, southEthiopia);
  const baselineNorthVal = getMean(baselineMean, northEthiopia);
  const baselineSouthVal = getMean(baselineMean, southEthiopia);

  // Execute all computations in a single request
  const results = ee.Dictionary({
    rn: recentNorthVal, rs: recentSouthVal,
    bn: baselineNorthVal, bs: baselineSouthVal
  }).getInfo();

  if (results.rn === null || results.rs === null || results.bn === null || results.bs === null) {
      console.log('C3: Calculation Failure. One or more regional means returned null.');
      console.log('A'); // Placeholder
      return;
  }

  // 5. Validation & Final Answer
  const anomalyNorth = results.rn - results.bn;
  const anomalySouth = results.rs - results.bs;

  const relativeAnomalyNorth = (anomalyNorth / results.bn) * 100;
  const relativeAnomalySouth = (anomalySouth / results.bs) * 100;

  console.log(`North 2021 Rainfall (mm): ${results.rn.toFixed(2)}`);
  console.log(`North LTA Rainfall (mm): ${results.bn.toFixed(2)}`);
  console.log(`North Relative Anomaly (%): ${relativeAnomalyNorth.toFixed(2)}`);

  console.log(`South 2021 Rainfall (mm): ${results.rs.toFixed(2)}`);
  console.log(`South LTA Rainfall (mm): ${results.bs.toFixed(2)}`);
  console.log(`South Relative Anomaly (%): ${relativeAnomalySouth.toFixed(2)}`);

  console.log(`Southern relative rainfall anomaly (${relativeAnomalySouth.toFixed(2)}%) was less than Northern (${relativeAnomalyNorth.toFixed(2)}%).`);

  if (relativeAnomalySouth < relativeAnomalyNorth) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during initialization or analysis:', e);
    console.log('D');
  }
}

initEE();
